import{_ as e,o as a,c as i,ae as r}from"./chunks/framework.Dh1jimFm.js";const m=JSON.parse('{"title":"The Translation Grid","description":"","frontmatter":{},"headers":[],"relativePath":"editor/translation-grid.md","filePath":"editor/translation-grid.md"}'),o={name:"editor/translation-grid.md"};function n(l,t,s,d,h,g){return a(),i("div",null,t[0]||(t[0]=[r('<h1 id="the-translation-grid" tabindex="-1">The Translation Grid <a class="header-anchor" href="#the-translation-grid" aria-label="Permalink to &quot;The Translation Grid&quot;">​</a></h1><p>The translation grid is where you spend most of your time: each row is a <strong>segment</strong> (usually a sentence or paragraph) with source and target text.</p><h2 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h2><p>The grid has five columns:</p><table tabindex="0"><thead><tr><th>Column</th><th>What it is</th></tr></thead><tbody><tr><td><strong>#</strong></td><td>Segment number (row index)</td></tr><tr><td><strong>Type</strong></td><td>Segment type (depends on the file format/importer)</td></tr><tr><td><strong>Source</strong></td><td>Original text (typically read-only)</td></tr><tr><td><strong>Target</strong></td><td>Your translation (editable)</td></tr><tr><td><strong>Status</strong></td><td>Segment status (dropdown)</td></tr></tbody></table><h2 id="editing-behavior" tabindex="-1">Editing behavior <a class="header-anchor" href="#editing-behavior" aria-label="Permalink to &quot;Editing behavior&quot;">​</a></h2><ul><li>The grid is optimized for speed, but edits are intentionally lightweight.</li><li><strong>Double-click</strong> a cell to edit.</li><li>Use <strong>Shift+Enter</strong> for a line break inside a cell (multi-line target).</li></ul><h2 id="confirming-status" tabindex="-1">Confirming &amp; status <a class="header-anchor" href="#confirming-status" aria-label="Permalink to &quot;Confirming &amp; status&quot;">​</a></h2><ul><li>Use the <strong>Status</strong> dropdown to set the segment state.</li><li>Keyboard confirm is supported (see <a href="./editing-confirming.html">Editing &amp; Confirming</a>).</li></ul><p>Common statuses include:</p><ul><li>Not started</li><li>Translated</li><li>Confirmed</li><li>Proofread</li><li>Approved</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If you plan to reimport into a CAT tool, do not merge/split content across segments. Segment boundaries must stay compatible.</p></div><h2 id="visual-cues" tabindex="-1">Visual cues <a class="header-anchor" href="#visual-cues" aria-label="Permalink to &quot;Visual cues&quot;">​</a></h2><ul><li><strong>Tags</strong> (CAT tool placeholders and formatting markers) are highlighted to make them hard to miss.</li><li><strong>Spellcheck</strong> (if enabled) underlines misspelled target words.</li><li><strong>Glossary matches</strong> can be highlighted in the source.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./navigation.html">Navigation</a></li><li><a href="./editing-confirming.html">Editing &amp; Confirming</a></li><li><a href="./keyboard-shortcuts.html">Keyboard Shortcuts</a></li><li><a href="./filtering.html">Filtering</a></li></ul>',16)]))}const c=e(o,[["render",n]]);export{m as __pageData,c as default};
